import storage from '@ohos.file.fs'
export class DeliveryBuffer {
  async prepare(location: string, bytes: Uint8Array, target: string): Promise<void> {
    const result = storage.openSync(location, storage.OpenMode.CREATE);
    storage.writeSync(result.fd, bytes.buffer);
    storage.closeSync(result);
    await unzip(location, target);
  }
}

